macro_rules! deps {
    () => {
        Result!();
    };
}

macro_rules! reset_pointer_authentication_keys {
    () => {
        deps!();
        # [doc = " Securely reset the thread's pointer authentication keys to fresh random"] # [doc = " values generated by the kernel."] # [doc = ""] # [doc = " # References"] # [doc = "  - [`prctl(PR_PAC_RESET_KEYS,…)`]"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Please ensure the conditions necessary to safely call this function,"] # [doc = " as detailed in the references above."] # [doc = ""] # [doc = " [`prctl(PR_PAC_RESET_KEYS,…)`]: https://man7.org/linux/man-pages/man2/prctl.2.html"] # [inline] # [cfg (linux_raw_dep)] pub unsafe fn reset_pointer_authentication_keys (keys : Option < PointerAuthenticationKeys > ,) -> io :: Result < () > { let keys = keys . as_ref () . map_or (0_u32 , PointerAuthenticationKeys :: bits) ; prctl_2args (PR_PAC_RESET_KEYS , keys as usize as * mut _) . map (| _r | ()) }
    };
}

reset_pointer_authentication_keys!()